20	MODEL_PATH="${MODEL_PATH:-${VERL_ROOT}/Qwen2.5-1.5B-Instruct}"
21	TRAIN_FILE="${TRAIN_FILE:-${VERL_ROOT}/taco_verl/train.parquet}"
22	TEST_FILE="${TEST_FILE:-${VERL_ROOT}/taco_verl/test.parquet}"
23	TACO_REWARD_PATH="${TACO_REWARD_PATH:-${VERL_ROOT}/verl/utils/reward_score/taco.py}"
24	
25	NNODES=${NNODES:-1}
26	NGPUS_PER_NODE=${NGPUS_PER_NODE:-8}
27	CUDA_VISIBLE_DEVICES="${CUDA_VISIBLE_DEVICES:-0,1,2,3,4,5,6,7}"
28	export CUDA_VISIBLE_DEVICES
29	
30	TRAIN_BATCH_SIZE=${TRAIN_BATCH_SIZE:-16}
31	PPO_MINI_BATCH_SIZE=${PPO_MINI_BATCH_SIZE:-16}
32	PPO_MICRO_BATCH_SIZE_PER_GPU=${PPO_MICRO_BATCH_SIZE_PER_GPU:-1}
33	LOG_PROB_MICRO_BATCH_SIZE_PER_GPU=${LOG_PROB_MICRO_BATCH_SIZE_PER_GPU:-1}
34	MAX_PROMPT_LENGTH=${MAX_PROMPT_LENGTH:-2048}
35	MAX_RESPONSE_LENGTH=${MAX_RESPONSE_LENGTH:-4096}
36	MAX_MODEL_LEN=$((MAX_PROMPT_LENGTH + MAX_RESPONSE_LENGTH))
37	
38	ACTOR_LR=${ACTOR_LR:-1e-6}
39	KL_LOSS_COEF=${KL_LOSS_COEF:-0}
40	USE_KL_LOSS=${USE_KL_LOSS:-False}
41	ENTROPY_COEFF=${ENTROPY_COEFF:-0}
42	
43	ROLLOUT_TP=${ROLLOUT_TP:-1}
44	ROLLOUT_GPU_MEM_UTIL=${ROLLOUT_GPU_MEM_UTIL:-0.4}
45	ROLLOUT_N=${ROLLOUT_N:-8}
46	VAL_TEMPERATURE=${VAL_TEMPERATURE:-0.7}
47	VAL_DO_SAMPLE=${VAL_DO_SAMPLE:-True}
48	REWARD_NUM_WORKERS=${REWARD_NUM_WORKERS:-32}
49	
50	PROJECT_NAME=${PROJECT_NAME:-verl_grpo_taco}
51	EXPERIMENT_NAME=${EXPERIMENT_NAME:-taco_qwen2_5_1.5b_torch_functional}
52	TEST_FREQ=${TEST_FREQ:-50}
53	TOTAL_EPOCHS=${TOTAL_EPOCHS:-15}
54	TOTAL_TRAINING_STEPS=${TOTAL_TRAINING_STEPS:-400}
55	# save_freq must be >0 or verl skips the final save too; equal to total steps => only last ckpt.
56	SAVE_FREQ=${SAVE_FREQ:-${TOTAL_TRAINING_STEPS}}
57	USE_V1=${USE_V1:-False}
58	
59	case "${DEVICE}" in
60	    gpu) ;;
61	    npu) NGPUS_PER_NODE=${NGPUS_PER_NODE:-8} ;;
62	    *)
63	        echo "Unsupported DEVICE=${DEVICE}. Expected 'gpu' or 'npu'." >&2
64	        exit 1
65	        ;;
66	esac
67	
68	DATA=(
69	    algorithm.adv_estimator=grpo
70	    data.train_files=${TRAIN_FILE}
71	    data.val_files=${TEST_FILE}
72	    data.train_batch_size=${TRAIN_BATCH_SIZE}
73	    data.max_prompt_length=${MAX_PROMPT_LENGTH}
74	    data.max_response_length=${MAX_RESPONSE_LENGTH}
75	    data.filter_overlong_prompts=True
76	    data.truncation='error'
77	    data.dataloader_num_workers=0
78	    algorithm.use_kl_in_reward=False
79	)
80	
81	MODEL=(
82	    actor_rollout_ref.model.path=${MODEL_PATH}
83	    actor_rollout_ref.model.use_remove_padding=True
84	    actor_rollout_ref.model.enable_gradient_checkpointing=True
85	    +actor_rollout_ref.model.override_config.attn_implementation=sdpa
86	)
87	
88	ACTOR=(
89	    actor_rollout_ref.actor.optim.lr=${ACTOR_LR}
90	    actor_rollout_ref.actor.ppo_mini_batch_size=${PPO_MINI_BATCH_SIZE}
91	    actor_rollout_ref.actor.ppo_micro_batch_size_per_gpu=${PPO_MICRO_BATCH_SIZE_PER_GPU}
92	    actor_rollout_ref.actor.use_kl_loss=${USE_KL_LOSS}
93	    actor_rollout_ref.actor.kl_loss_coef=${KL_LOSS_COEF}
94	    actor_rollout_ref.actor.kl_loss_type=low_var_kl
95	    actor_rollout_ref.actor.entropy_coeff=${ENTROPY_COEFF}
96	    actor_rollout_ref.actor.fsdp_config.param_offload=False
97	    actor_rollout_ref.actor.fsdp_config.optimizer_offload=False
98	)
99	
100	ROLLOUT=(
101	    actor_rollout_ref.rollout.log_prob_micro_batch_size_per_gpu=${LOG_PROB_MICRO_BATCH_SIZE_PER_GPU}
102	    actor_rollout_ref.rollout.tensor_model_parallel_size=${ROLLOUT_TP}
103	    actor_rollout_ref.rollout.name=${INFER_BACKEND}
104	    actor_rollout_ref.rollout.gpu_memory_utilization=${ROLLOUT_GPU_MEM_UTIL}
105	    actor_rollout_ref.rollout.enable_chunked_prefill=False
106	    actor_rollout_ref.rollout.enforce_eager=False
107	    actor_rollout_ref.rollout.free_cache_engine=True
108	    actor_rollout_ref.rollout.max_model_len=${MAX_MODEL_LEN}
109	    actor_rollout_ref.rollout.max_num_batched_tokens=${MAX_MODEL_LEN}
110	    actor_rollout_ref.rollout.n=${ROLLOUT_N}
111	    actor_rollout_ref.rollout.val_kwargs.temperature=${VAL_TEMPERATURE}
112	    actor_rollout_ref.rollout.val_kwargs.do_sample=${VAL_DO_SAMPLE}
113	)
114	
115	REF=(
116	    actor_rollout_ref.ref.log_prob_micro_batch_size_per_gpu=${LOG_PROB_MICRO_BATCH_SIZE_PER_GPU}
117	    actor_rollout_ref.ref.fsdp_config.param_offload=True
118	)
119	
120	REWARD=(
121	    reward.num_workers=${REWARD_NUM_WORKERS}
122	    reward.reward_manager.name=naive
123	    reward.custom_reward_function.path=${TACO_REWARD_PATH}
124	    reward.custom_reward_function.name=compute_score
125	)
126	
127	TRAINER=(
128	    trainer.critic_warmup=0
129	    trainer.logger='["console","wandb"]'
130	    trainer.project_name=${PROJECT_NAME}
131	    trainer.experiment_name=${EXPERIMENT_NAME}
132	    trainer.n_gpus_per_node=${NGPUS_PER_NODE}
133	    trainer.nnodes=${NNODES}
134	    trainer.save_freq=${SAVE_FREQ}
135	    trainer.test_freq=${TEST_FREQ}
136	    trainer.total_epochs=${TOTAL_EPOCHS}
137	    trainer.total_training_steps=${TOTAL_TRAINING_STEPS}
138	    trainer.use_v1=${USE_V1}
139	)
140	
141	echo "Logging to ${LOG_FILE}"
142	export PYTHONPATH="${VERL_ROOT}:${PYTHONPATH:-}"
143	
144	python3 -m verl.trainer.main_ppo \
145	    "${DATA[@]}" \
146	    "${MODEL[@]}" \
147	    "${ACTOR[@]}" \
148	    "${ROLLOUT[@]}" \
149	    "${REF[@]}" \
150	    "${REWARD[@]}" \
151	    "${TRAINER[@]}" \
152	    "$@" \
153	    >"${LOG_FILE}" 2>&1
